mapper.select:
SELECT pro.p_name as pName,eh.*, COALESCE(cn.cName, '') AS winningUnitName from Eng_Honor eh left join (select ehu.eh_id,LISTAGG(sc.c_name, ', ') WITHIN GROUP (ORDER BY sc.c_name) AS cName from Eng_Honor_Unit ehu left join SYS_Company sc ON sc.C_ID = ehu.unit_id GROUP BY ehu.eh_id) cn ON eh.id = cn.eh_id left join pre_project pro on eh.award_Winning_Project=pro.p_id
and eh.award_name like concat('%',#{params.awardName},'%')
and eh.award_type = #{params.awardType}
and eh.award_level = #{params.awardLevel}
and eh.award_winning_project=#{params.awardWinningProject}
and likePname(#{params.pName},pro.P_Id)=true
and pro.p_name like concat('%',#{params.pName},'%')
and eh.award_department like concat('%',#{params.awardDepartment},'%')
and cn.cName like concat('%',#{params.winningUnitName},'%')

select pro.p_name as pName,eh.*,COALESCE(cn.cName, '') AS winningUnitName FROM Eng_Honor eh LEFT JOIN(SELECT ehu.eh_id,GROUP_CONCAT(sc.c_name ORDER BY sc.c_name SEPARATOR ', ') AS cName FROM Eng_Honor_Unit ehu LEFT JOIN SYS_Company sc ON sc.C_ID = ehu.unit_id GROUP BY ehu.eh_id) cn ON eh.id = cn.eh_id left join pre_project pro on eh.award_Winning_Project=pro.p_id
and eh.award_name like concat('%',#{params.awardName},'%')
and eh.award_type = #{params.awardType}
and eh.award_level = #{params.awardLevel}
and eh.award_winning_project=#{params.awardWinningProject}
and likePname(#{params.pName},pro.P_Id)=true
and pro.p_name like concat('%',#{params.pName},'%')
and eh.award_department like concat('%',#{params.awardDepartment},'%')
and cn.cName like concat('%',#{params.winningUnitName},'%')
